import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.BU4O3IzQ.js";const m=JSON.parse('{"title":"AI 动态 · 2026-08-03","description":"","frontmatter":{"title":"AI 动态 · 2026-08-03","date":"2026-08-03T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-03.md","filePath":"news/2026-08/ai-news-2026-08-03.md","lastUpdated":1786092171000}'),n={name:"news/2026-08/ai-news-2026-08-03.md"};function i(o,e,c,p,l,d){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-08-03" tabindex="-1">AI 动态 · 2026-08-03 <a class="header-anchor" href="#ai-动态-·-2026-08-03" aria-label="Permalink to &quot;AI 动态 · 2026-08-03&quot;">​</a></h1><blockquote><p>截至 2026-08-03。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="华为诺亚开源mindmemos-让ai-agent记忆可迁移、自演进" tabindex="-1">华为诺亚开源MindMemOS：让AI Agent记忆可迁移、自演进 <a class="header-anchor" href="#华为诺亚开源mindmemos-让ai-agent记忆可迁移、自演进" aria-label="Permalink to &quot;华为诺亚开源MindMemOS：让AI Agent记忆可迁移、自演进&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-03">2026-08-03</time></p><p>华为诺亚方舟实验室开源面向AI Agent的可迁移、自演进记忆操作层MindMemOS。它用「实体-属性-时间」三维结构保存最新状态与完整演化轨迹，通过MindSchema预设提取规则、Feedback挖掘用户纠偏反馈、Dreaming离线巩固记忆，让记忆系统随使用持续进化。在LoCoMo上取得94.03分，在MemoryAgentBench的FactConsolidation测试中压缩19.4%-23.5%活跃记忆的同时将问答准确率最高提升10.3个百分点。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/464835.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="aws计费系统故障-用户收到数万亿美元账单预估-告警系统未能阻止问题扩大" tabindex="-1">AWS计费系统故障：用户收到数万亿美元账单预估，告警系统未能阻止问题扩大 <a class="header-anchor" href="#aws计费系统故障-用户收到数万亿美元账单预估-告警系统未能阻止问题扩大" aria-label="Permalink to &quot;AWS计费系统故障：用户收到数万亿美元账单预估，告警系统未能阻止问题扩大&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-03">2026-08-03</time></p><p><img src="https://static001.infoq.cn/resource/image/46/cf/465ec3bed997yya8c61435211d96eacf.jpg" alt="配图"></p><p>7月16日AWS计费计算系统配置变更导致单价错误，用户预估账单飙升至数百万至数万亿美元，持续超24小时。AWS承认告警系统检测到成本异常但未能阻止生成流程，也未通知工程团队，直到4.5小时后收到客户反馈才意识到问题。该事件暴露了云成本管理中的告警响应机制缺陷，引发对云服务商内部运维流程的广泛讨论。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/ogvAbgp1eFp6ddoommVh?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="年薪百万抢电工-meta等ai巨头自办技校应对数据中心建设瓶颈" tabindex="-1">年薪百万抢电工：Meta等AI巨头自办技校应对数据中心建设瓶颈 <a class="header-anchor" href="#年薪百万抢电工-meta等ai巨头自办技校应对数据中心建设瓶颈" aria-label="Permalink to &quot;年薪百万抢电工：Meta等AI巨头自办技校应对数据中心建设瓶颈&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-03">2026-08-03</time></p><p>AI数据中心建设面临严重电工短缺，麦肯锡预计美国2023至2030年需额外培养13万名电工。AI公司支付高溢价，优秀电工年薪达24万-28万美元，但一个60兆瓦项目每月因招工短缺延迟交付损失1420万美元。微软总裁称电工短缺是扩建数据中心头号障碍。2026年Alphabet和Meta投入技工培训成本合计达2.65亿美元，Meta拨款1.15亿自办培训项目。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/465223.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="阿里「千问办公」开启公测-整合三款产品瞄准企业级agent市场" tabindex="-1">阿里「千问办公」开启公测，整合三款产品瞄准企业级Agent市场 <a class="header-anchor" href="#阿里「千问办公」开启公测-整合三款产品瞄准企业级agent市场" aria-label="Permalink to &quot;阿里「千问办公」开启公测，整合三款产品瞄准企业级Agent市场&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-03">2026-08-03</time></p><p>阿里巴巴旗下企业级Agent产品「千问办公」（QwenWork）开启公测，个人和企业用户均可通过官网体验，网页版和独立PC客户端已开放，钉钉内置入口近期开放。该产品由QoderWork、MuleRun、悟空三款产品整合而来，是业内首款同时支持桌面端Agent、云端Agent、企业协同Agent的产品，已初步打通钉钉IM，未来将连接企业真实数据库和工作流。公测期间新用户注册可获得2000积分。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/465211.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="openai新模型「astra」曝光-多智能体协同攻克数学难题-或成美国首批过审模型" tabindex="-1">OpenAI新模型「Astra」曝光：多智能体协同攻克数学难题，或成美国首批过审模型 <a class="header-anchor" href="#openai新模型「astra」曝光-多智能体协同攻克数学难题-或成美国首批过审模型" aria-label="Permalink to &quot;OpenAI新模型「Astra」曝光：多智能体协同攻克数学难题，或成美国首批过审模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-03">2026-08-03</time></p><p><img src="https://static001.infoq.cn/resource/image/yy/e9/yye9883d552b0cda4f2d9ccf698dbbe9.png" alt="配图"></p><p>据The Information报道，OpenAI正在测试代号「Astra」的全新模型家族，核心能力是让多个智能体在较长时间内协同工作、解决高难度问题。Altman已在华盛顿向政策制定者演示，并展示了系统解决此前未被攻克的数学难题的能力。Astra可能作为GPT-5系列后续版本或直接命名为GPT-6，与Sol、Terra和Luna并列成为OpenAI新模型类别。该模型还能让个人独立完成过去需外包的专业工作。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/uRoTVrUKptoRHzFwSpxj?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="deepseek-v4-flash正式版发布-基准测试优于pro预览版-价格下调" tabindex="-1">DeepSeek V4 Flash正式版发布：基准测试优于Pro预览版，价格下调 <a class="header-anchor" href="#deepseek-v4-flash正式版发布-基准测试优于pro预览版-价格下调" aria-label="Permalink to &quot;DeepSeek V4 Flash正式版发布：基准测试优于Pro预览版，价格下调&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">少数派</span><time datetime="2026-08-03">2026-08-03</time></p><p>DeepSeek发布V4 Flash正式版，在多个基准测试中得分优于V4 Pro预览版。模型结构与预览版一致，总参数量284B、激活13B，仅重新进行后训练。价格方面，每百万tokens缓存未命中输入从2元下调至1元，输出从3元下调至2元。DeepSeek称V4 Pro正式版将尽快发布。此前DeepSeek完成约500亿元首次对外融资，估值超3500亿元，并正努力将所有部门规模扩大至少一倍。</p><p class="news-entry-source"><a href="https://sspai.com/post/113014" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="jamiepine-voicebox-开源ai语音工作室-支持克隆、听写与创作" tabindex="-1">jamiepine/voicebox：开源AI语音工作室，支持克隆、听写与创作 <a class="header-anchor" href="#jamiepine-voicebox-开源ai语音工作室-支持克隆、听写与创作" aria-label="Permalink to &quot;jamiepine/voicebox：开源AI语音工作室，支持克隆、听写与创作&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">jamiepine/voicebox</span><time datetime="2026-08-03">2026-08-03</time></p><p><img src="https://opengraph.githubassets.com/1/jamiepine/voicebox" alt="配图"></p><p>jamiepine/voicebox是一个开源的AI语音工作室项目，提供语音克隆、听写和创作能力。项目定位为完整的AI语音工具集，开发者可基于此构建语音相关的应用。作为开源项目，它允许社区自由使用、修改和分发，为语音AI领域的开发者提供了一个可扩展的基础设施选择。</p><p class="news-entry-source"><a href="https://github.com/jamiepine/voicebox" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="livekit-agents-构建实时语音ai-agent的开源框架" tabindex="-1">livekit/agents：构建实时语音AI Agent的开源框架 <a class="header-anchor" href="#livekit-agents-构建实时语音ai-agent的开源框架" aria-label="Permalink to &quot;livekit/agents：构建实时语音AI Agent的开源框架&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">livekit/agents</span><time datetime="2026-08-03">2026-08-03</time></p><p><img src="https://opengraph.githubassets.com/1/livekit/agents" alt="配图"></p><p>livekit/agents是一个用于构建实时语音AI Agent的开源框架，支持语音和视频交互场景。该框架为开发者提供了构建实时语音助手、视频智能体等应用的基础能力，与LiveKit的实时通信基础设施深度集成。对于需要快速搭建语音交互Agent的团队，这是一个值得关注的开源选择。</p><p class="news-entry-source"><a href="https://github.com/livekit/agents" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="firecrawl-pdf-inspector-rust编写的pdf智能检测与文本提取库" tabindex="-1">firecrawl/pdf-inspector：Rust编写的PDF智能检测与文本提取库 <a class="header-anchor" href="#firecrawl-pdf-inspector-rust编写的pdf智能检测与文本提取库" aria-label="Permalink to &quot;firecrawl/pdf-inspector：Rust编写的PDF智能检测与文本提取库&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">firecrawl/pdf-inspector</span><time datetime="2026-08-03">2026-08-03</time></p><p><img src="https://opengraph.githubassets.com/1/firecrawl/pdf-inspector" alt="配图"></p><p>firecrawl/pdf-inspector是一个用Rust编写的高性能PDF检查、分类和文本提取库。它能智能检测扫描版PDF与文本版PDF，帮助开发者做出智能路由决策。该库定位为快速、可靠的PDF处理工具，适用于需要批量处理PDF文档并区分扫描件与电子文档的场景，可作为文档处理管线的底层组件。</p><p class="news-entry-source"><a href="https://github.com/firecrawl/pdf-inspector" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="free-claude-code-在终端、ide或手机免费使用claude-code、codex和pi" tabindex="-1">free-claude-code：在终端、IDE或手机免费使用Claude Code、Codex和Pi <a class="header-anchor" href="#free-claude-code-在终端、ide或手机免费使用claude-code、codex和pi" aria-label="Permalink to &quot;free-claude-code：在终端、IDE或手机免费使用Claude Code、Codex和Pi&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Alishahryar1/free-claude-code</span><time datetime="2026-08-03">2026-08-03</time></p><p><img src="https://opengraph.githubassets.com/1/Alishahryar1/free-claude-code" alt="配图"></p><p>Alishahryar1/free-claude-code是一个开源项目，让用户从终端、应用、IDE或手机免费使用Claude Code、Codex和Pi等AI编程工具，并支持语音交互。该项目类似OpenClaw的体验，为开发者提供了免费访问多个主流AI编码助手的途径，降低了使用门槛。对于希望低成本体验不同AI编程工具的开发者，这是一个实用的开源方案。</p><p class="news-entry-source"><a href="https://github.com/Alishahryar1/free-claude-code" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="anthropic详解claude安全隔离架构-沙箱使权限确认弹窗减少84" tabindex="-1">Anthropic详解Claude安全隔离架构：沙箱使权限确认弹窗减少84% <a class="header-anchor" href="#anthropic详解claude安全隔离架构-沙箱使权限确认弹窗减少84" aria-label="Permalink to &quot;Anthropic详解Claude安全隔离架构：沙箱使权限确认弹窗减少84%&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-03">2026-08-03</time></p><p><img src="https://static001.infoq.cn/resource/image/b3/2a/b31907e118e2e82ce289c1d5b6b6b12a.jpg" alt="配图"></p><p>Anthropic详细介绍了Claude在Web、开发者和桌面产品中的安全隔离架构，强调Agent安全不能仅依赖权限确认或模型自身机制，更需通过文件系统、网络和执行环境建立确定性安全边界。Claude Code引入操作系统级沙箱（macOS Seatbelt、Linux bubblewrap）后，权限确认弹窗数量减少84%。文章还披露了Claude Code在用户确认前解析项目配置文件的漏洞事件及修复方案。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/0j39GYLo41A3VMv9BoOi?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>（本日无新条目）</p></div>',8)])])}const u=a(n,[["render",i]]);export{m as __pageData,u as default};
